-- 39-sample-records.sql — every item that waits on DBEDC, built out with SAMPLE data.
--
-- Named officers (control room, customer service, grievance focal and appeal,
-- RTI designated officer and appellate authority, media, integrity), the
-- document libraries lenders and the RTI Act expect (resettlement plan,
-- entitlement matrix, monitoring reports, IEE/ECC, annual report, audited
-- accounts, policies, tariff notifications), a key-facts table with source and
-- date, and awards. Every sample carries the word "Sample" / "নমুনা" / "示例"
-- in a visible field. The register of what to replace is
-- docs/handover/2026-09-14-information-to-replace.md.
--
-- Also: sample S.R.O. citations on the toll records for the open section,
-- sample company identity settings, and the DBEDC control-room number, so the
-- toll table cites an instrument and the footer shows both numbers.
--
-- Additions are guarded on their own wording. Safe to import twice.

SET NAMES utf8mb4;

-- ---------------------------------------------------------------- addition to contact
SET @p = (SELECT `id` FROM `pages` WHERE `slug` = 'contact');
SET @has = (SELECT COUNT(*) FROM `blocks` b JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en' WHERE b.`page_id` = @p AND b.`type` = 'contact-directory' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Who to contact');
SET @ok = (@p IS NOT NULL AND @has = 0);
SET @last = (SELECT `id` FROM `blocks` WHERE `page_id` = @p ORDER BY `sort_order` DESC, `id` DESC LIMIT 1);
SET @lastsort = (SELECT `sort_order` FROM `blocks` WHERE `id` = @last);
SET @endcta = (SELECT `type` = 'cta-band' FROM `blocks` WHERE `id` = @last);
UPDATE `blocks` SET `sort_order` = `sort_order` + 1 WHERE `id` = @last AND @ok AND @endcta = 1;
INSERT INTO `blocks` (`page_id`, `type`, `sort_order`, `status`) SELECT @p, 'contact-directory', IF(@endcta = 1, @lastsort, COALESCE(@lastsort, 0) + 1), 'published' FROM DUAL WHERE @ok;
SET @b = IF(@ok, LAST_INSERT_ID(), NULL);
INSERT INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'en', '{"heading":"Who to contact","intro":"Role lines and mailboxes. Names, numbers and addresses shown here are sample entries until DBEDC confirms them.","items":[{"department":"Control room","role":"24-hour incident line","name":"Sample officer: Duty Controller","phone":"+880 2 5555 0199","email":"control@dhakabypass.com","hours":"24 hours, every day","notes":"Sample entry. Breakdowns, crashes, obstructions on the expressway."},{"department":"Customer service","role":"Toll and account enquiries","name":"","phone":"+880 2 5555 0100","email":"info@dhakabypass.com","hours":"Sunday–Thursday 9:00–17:00","notes":"Sample entry."},{"department":"Grievances","role":"Grievance Redress focal officer","name":"Sample officer: Manager, Customer Relations","phone":"+880 2 5555 0101","email":"grievance@dhakabypass.com","hours":"Sunday–Thursday 9:00–17:00","notes":"Sample entry. First-instance answer within the published deadline."},{"department":"Grievances","role":"Appeal officer","name":"Sample officer: Head of Operations","phone":"+880 2 5555 0102","email":"appeals@dhakabypass.com","hours":"Sunday–Thursday 9:00–17:00","notes":"Sample entry. Reviews a grievance the focal officer''s answer did not resolve, within 15 working days."},{"department":"Right to information","role":"Designated Information Officer (RTI Act 2009, s.10)","name":"Sample officer: Company Secretary","phone":"+880 2 5555 0103","email":"rti@dhakabypass.com","hours":"Sunday–Thursday 9:00–17:00","notes":"Sample entry. Requests answered within 20 working days; 30 where a third party is involved."},{"department":"Right to information","role":"Appellate authority","name":"Sample officer: Chief Executive Officer","phone":"","email":"rti-appeal@dhakabypass.com","hours":"","notes":"Sample entry. Appeal within 30 days of a refusal or a missed deadline."},{"department":"Media","role":"Press and media enquiries","name":"Sample officer: Communications Manager","phone":"+880 2 5555 0104","email":"media@dhakabypass.com","hours":"Sunday–Thursday 9:00–17:00","notes":"Sample entry."},{"department":"Integrity","role":"Integrity focal point (National Integrity Strategy)","name":"Sample officer: Head of Internal Audit","phone":"","email":"integrity@dhakabypass.com","hours":"","notes":"Sample entry. Reports of corruption or misconduct; anonymous reports accepted."}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
